// Updated AdminDepositRequests.jsx with styled table
import React, { useState, useEffect } from "react";

function AdminDepositRequests({ onCancel }) {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState("");

  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchPendingDeposits();
  }, []);

  const fetchPendingDeposits = async () => {
    setLoading(true);
    try {
      const response = await fetch("http://localhost:8080/api/deposit/pending", {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (!response.ok) throw new Error("ডিপোজিট লোড করা যায়নি");

      const data = await response.json();
      setRequests(data);
      setError(null);
    } catch (err) {
      console.error("Fetch Error:", err);
      setError("ডেটা লোড করতে সমস্যা হয়েছে");
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id) => {
    try {
      const res = await fetch(`http://localhost:8080/api/deposit/approve/${id}`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (!res.ok) throw new Error("অ্যাপ্রুভ ব্যর্থ");

      setMessage("সফলভাবে অ্যাপ্রুভ হয়েছে");
      fetchPendingDeposits();
    } catch (err) {
      console.error("Approve Error:", err);
      setMessage("অ্যাপ্রুভ করা যায়নি");
    }
  };

  const handleReject = async (id) => {
    try {
      const res = await fetch(`http://localhost:8080/api/deposit/reject/${id}`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (!res.ok) throw new Error("রিজেক্ট ব্যর্থ");

      setMessage("সফলভাবে রিজেক্ট হয়েছে");
      fetchPendingDeposits();
    } catch (err) {
      console.error("Reject Error:", err);
      setMessage("রিজেক্ট করা যায়নি");
    }
  };

  const tableStyles = {
    width: "100%",
    border: "1px solid #ccc",
    borderCollapse: "collapse",
    boxShadow: "0 0 8px rgba(0,0,0,0.1)",
    marginTop: "20px",
  };

  const thtdStyles = {
    border: "1px solid #ccc",
    padding: "10px",
    textAlign: "center",
  };

  const buttonStyles = {
    approve: {
      backgroundColor: "#28a745",
      color: "white",
      padding: "6px 10px",
      border: "none",
      borderRadius: "4px",
      marginRight: "5px",
      cursor: "pointer",
    },
    reject: {
      backgroundColor: "#dc3545",
      color: "white",
      padding: "6px 10px",
      border: "none",
      borderRadius: "4px",
      cursor: "pointer",
    },
  };

  return (
    <div style={{ padding: "20px", fontFamily: "Segoe UI, sans-serif" }}>
      <h2 style={{ textAlign: "center", fontSize: "28px", marginBottom: "10px" }}>🧾 পেন্ডিং ডিপোজিট রিকোয়েস্ট</h2>

      {message && (
        <div
          style={{
            margin: "15px 0",
            padding: "10px",
            borderRadius: "5px",
            backgroundColor: message.includes("অ্যাপ্রুভ") || message.includes("সফল") ? "#d4edda" : "#f8d7da",
            color: message.includes("অ্যাপ্রুভ") || message.includes("সফল") ? "#155724" : "#721c24",
            fontWeight: "600",
          }}
        >
          {message}
        </div>
      )}

      {loading && <p>লোড হচ্ছে...</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}
      {!loading && !error && requests.length === 0 && <p>কোনো পেন্ডিং রিকোয়েস্ট নেই।</p>}

      {!loading && !error && requests.length > 0 && (
        <table style={tableStyles}>
          <thead style={{ backgroundColor: "#f1f1f1" }}>
            <tr>
              <th style={thtdStyles}>ID</th>
              <th style={thtdStyles}>Email</th>
              <th style={thtdStyles}>Amount</th>
              <th style={thtdStyles}>Method</th>
              <th style={thtdStyles}>Txn ID</th>
              <th style={thtdStyles}>Sender Number</th>
              <th style={thtdStyles}>Status</th>
              <th style={thtdStyles}>Date</th>
              <th style={thtdStyles}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {requests.map((req) => (
              <tr key={req.id} style={{ backgroundColor: "#fff" }}>
                <td style={thtdStyles}>{req.id}</td>
                <td style={thtdStyles}>{req.email || "N/A"}</td>
                <td style={thtdStyles}>৳ {Number(req.amount).toFixed(2)}</td>
                <td style={thtdStyles}>{req.method || "N/A"}</td>
                <td style={thtdStyles}>{req.transactionId || "N/A"}</td>
                <td style={thtdStyles}>{req.senderNumber || "N/A"}</td>
                <td style={thtdStyles}>{req.status}</td>
                <td style={thtdStyles}>{req.requestedAt ? new Date(req.requestedAt).toLocaleString() : "N/A"}</td>
                <td style={thtdStyles}>
                  <button
                    onClick={() => handleApprove(req.id)}
                    disabled={req.status !== "PENDING"}
                    style={buttonStyles.approve}
                  >
                    Approve
                  </button>
                  <button
                    onClick={() => handleReject(req.id)}
                    disabled={req.status !== "PENDING"}
                    style={buttonStyles.reject}
                  >
                    Reject
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <button
        style={{
          marginTop: "20px",
          padding: "10px 20px",
          backgroundColor: "#007bff",
          color: "white",
          border: "none",
          borderRadius: "5px",
          cursor: "pointer",
        }}
        onClick={onCancel}
      >
        ⬅️ হোমে ফিরে যান
      </button>
    </div>
  );
}

export default AdminDepositRequests;
